    long long dot5 = (p[5].x - p[2].x) * dx + (p[5].y - p[2].y) * dy;
    if (dot4 >= dot5) {
        printf("N\n");
        return 0;
    }

    // 9. P1 e P6 separados pela reta P2P3
    long long c1 = cross(p[2], p[3], p[1]);
    long long c6 = cross(p[2], p[3], p[6]);
    if (!((c1 > 0 && c6 < 0) || (c1 < 0 && c6 > 0))) {
        printf("N\n");
        return 0;
    }

    // 10. P1 e P7 separados pela reta P2P3
    long long c7 = cross(p[2], p[3], p[7]);
